{
    if (!m_worktreesTable)
        return QString();
    for (int row = 0; row < m_worktreesTable->rowCount(); ++row) {
        QTableWidgetItem *b = m_worktreesTable->item(row, 0);
        if (b && b->data(Qt::UserRole).toString() == branch) {
            if (QTableWidgetItem *ab = m_worktreesTable->item(row, 3))
                return ab->text();
        }
    }
    return QString();
}

