    connect(m_pullConflictDetails, &QLabel::linkActivated, this,
            [this](const QString &) {
                if (m_pullTabFiles)
                    m_pullTabFiles->setChecked(true);
                if (m_pullSubStack)
                    m_pullSubStack->setCurrentIndex(3);
            });

